sys_script.script:
(function executeRule(current, previous) {

    var taxable = parseFloat(current.taxable_amount) || 0;
    var cgst = parseFloat(current.cgst_amount) || 0;
    var sgst = parseFloat(current.sgst_amount) || 0;
    var igst = parseFloat(current.igst_amount) || 0;

    var expected = taxable + cgst + sgst + igst;
    var actual = parseFloat(current.total_invoice_amount) || 0;

    if (Math.abs(expected - actual) > 0.01) {
        gs.addErrorMessage(
            'Invoice total must equal taxable amount plus GST.'
        );
        current.setAbortAction(true);
    }

})(current, previous);
